package net.civeira.phylax.feature.notification.message.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.message.domain.Message;
import net.civeira.phylax.feature.notification.message.domain.valueobject.RetriesVO;

class RetriesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retries of message")
  void test_retries_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetriesValueHolder<Object> value = new RetriesValueHolder<>(holder);
    Assertions.assertSame(holder, value.retries(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetriesValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetries().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retries of message")
  void test_retries_value_holder_assign_value_object() {
    Object holder = new Object();
    RetriesValueHolder<Object> value = new RetriesValueHolder<>(holder);
    RetriesVO vo = RetriesVO.from(1);
    Assertions.assertFalse(value.getRetriesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.retries(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetriesValue().orElseThrow());
    Assertions.assertSame(holder, value.retries(Optional.empty()));
    Assertions.assertFalse(value.getRetriesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retries(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetriesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retries of message against the original")
  void test_retries_value_holder_read() {
    Object holder = new Object();
    RetriesValueHolder<Object> value = new RetriesValueHolder<>(holder);
    RetriesVO vo = RetriesVO.from(1);
    RetriesVO other = RetriesVO.from(1);
    Message original = Mockito.mock(Message.class);
    Mockito.when(original.getRetriesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetries(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetries(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retries(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetries(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetries(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retries of message")
  void test_retries_value_holder_unset() {
    Object holder = new Object();
    RetriesValueHolder<Object> value = new RetriesValueHolder<>(holder);
    RetriesVO vo = RetriesVO.from(1);
    value.retries(vo);
    Assertions.assertSame(holder, value.unsetRetriesIfMatches("retries_other"));
    Assertions.assertTrue(value.getRetriesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetriesIfMatches("retries"));
    Assertions.assertFalse(value.getRetriesValue().isPresent(),
        "The field name must clear the value");
    value.retries(vo);
    Assertions.assertSame(holder, value.unsetRetries());
    Assertions.assertFalse(value.getRetriesValue().isPresent(), "Unset must clear the value");
  }
}
